    return _link(label or f["source"].replace("СН 1.03.04-2020, ", "").replace("СП 4.01.08-2024, ", "СП 4.01.08, ").replace("СП 4.02.08-2024, ", "СП 4.02.08, ").replace("СП 4.02.07-2024, ", "СП 4.02.07, ").replace("СП 4.01.07-2024, ", "СП 4.01.07, "), f"{BASE}/akty#{fid}")


