def poryadok_body():
    s = ""
    s += _kpis([("2 редакции", "Перечень № 47 (2024) и новая редакция по № 84 (2026)"),
                ("1 сутки", "уведомить участников о готовности актов до освидетельствования (электронный вид)"),
                ("3 рабочих дня", "проверка проектов актов и визирование ЭЦП"),
                ("7 разделов", "в журнале производства работ")])
    s += _sec("1", "Что обязан оформлять подрядчик",
              _p("Обязанности подрядчика (застройщика) на объекте строительства определяет СН 1.03.04-2020, п. 4.11. Среди прочего он должен:")
              + _ul(["осуществлять производственный контроль с оформлением результатов исполнительной документацией;",
                     "вести журнал производства работ по форме и правилам приложения Б и специальные журналы по видам работ; совместно с проектировщиком фиксировать выполнение указаний авторского надзора в журнале авторского надзора;",
                     "составлять акты освидетельствования скрытых работ, промежуточной приёмки ответственных конструкций, испытаний и опробования оборудования, систем, сетей и устройств;",
                     "оформлять другую производственную документацию, которую требуют ТНПА на отдельные виды работ."])
              + _note("Состав исполнительной документации устанавливает Перечень, утверждённый Минстройархитектуры на основании подп. 1.27 п. 1 ст. 22 Кодекса об архитектурной, градостроительной и строительной деятельности."))
    s += _sec("2", "Какой Перечень действует",
              _status_box()
              + _p("Что изменилось в новой редакции по сравнению с первой:")
              + _ul(["перечень стал короче: из 21 позиции осталось 14;",
                     "акты испытаний собраны в одну позицию 9 и расписаны по 26 видам: появились участки трубопроводов и колодцы, ёмкостные сооружения, воздуховоды вентиляции, газо- и электроснабжение, тепловой пункт (котельная), тепловые сети;",
                     "индивидуальные испытания разделены на системы вентиляции и смонтированное оборудование;",
                     "специальные журналы названы поимённо (13 видов);",
                     "перечень смонтированного оборудования объединён с паспортами на него."])
              + _p("Из первой редакции исключены:")
              + _ul(REMOVED)
              + _note("Исключение позиции из Перечня не отменяет требований других документов: договор подряда и ТНПА на вид работ могут по-прежнему требовать соответствующих документов."))
    s += _sec("3", "Перечень документов (новая редакция)", _peren_table())
    s += _sec("4", "Акты: кто подписывает и как оформляют",
              _p("Формы актов освидетельствования скрытых работ и промежуточной приёмки ответственных конструкций приведены в приложениях Л и М к СН 1.03.04-2020. Комиссия по этим формам: представитель подрядчика, представитель субподрядной организации (если работы выполняла она), представитель технического надзора и представитель авторского надзора. Каждый подписывает с указанием даты и времени.")
              + _ul(["Скрытые работы подлежат приёмке с составлением акта. Акт составляют на завершённый процесс.",
                     "Если последующие работы должны начаться после перерыва, освидетельствование и акт повторяют непосредственно перед ними.",
                     "<b>Запрещено выполнять последующие работы без актов освидетельствования предшествующих скрытых работ.</b> После повреждения уже принятых работ их освидетельствуют повторно.",
                     "Ответственные конструкции принимают по мере готовности с участием технического и авторского надзора.",
                     "Для сложных объектов акты составляют с учётом особых указаний и технических условий проекта.",
                     "Подписанные акты нумеруют, регистрируют в журнале производства работ, хранят у подрядчика и предъявляют приёмочной комиссии вместе с журналом (СН 1.03.04, п. 8.9–8.12)."])
              + _p("Акты испытаний систем водоснабжения, канализации, отопления и вентиляции составляет комиссия из представителей заказчика, генерального подрядчика и строительно-монтажной организации; при испытаниях вентиляции в комиссию входит лаборатория (испытательное подразделение). Формы и методики испытаний даны в СП 4.01.08-2024, СП 4.02.08-2024, СП 4.02.07-2024 и (для наружных сетей) СП 4.01.07-2024. Состав комиссии в онлайн-бланке можно менять: снимите галочку у участника, которого в акте быть не должно.")
              + f'<p class="e-lead2">{_link("Заполнить акт онлайн →", BASE + "/akty")}</p>')
    s += _sec("5", "Журнал производства работ",
              _p("Журнал — основной производственный документ: он отражает технологическую последовательность, сроки, качество и условия выполнения работ. Форма и правила ведения даны в приложении Б к СН 1.03.04-2020 (по форме и правилам постановления Совета Министров № 383 от 18.03.2010). Журнал состоит из семи разделов:")
              + _tbl(["Раздел", "Содержание", "Кто заполняет"], [
                  ["1", "Общие сведения: объект, разрешение на СМР или уведомление, ответственные лица, сроки, показатели объекта, субподрядчики", "Генподрядчик (подрядчик) или застройщик до начала работ, с участием проектной организации и заказчика"],
                  ["2", "Список инженерно-технического персонала на объекте", "Руководитель генподрядчика или застройщика"],
                  ["3", "Перечень актов промежуточной приёмки и освидетельствования скрытых работ", "Ответственный за производство работ, в хронологическом порядке"],
                  ["4", "Сведения о производстве СМР с результатами операционного контроля качества", "Ответственный за производство работ, ежедневно с первого дня"],
                  ["5", "Перечень специальных журналов работ", "Ответственный за производство работ"],
                  ["6", "Замечания лиц, контролирующих производство и безопасность работ", "Контролирующие лица, представители проектной организации и авторского надзора"],
                  ["7", "Сведения о мероприятиях технического (технологического, поверочного) характера контролирующих органов", "Контролирующие (надзорные) органы"],
              ])
              + _ul(["Журнал ведут на каждом объекте. Он должен быть пронумерован, прошнурован и скреплён печатью выдавшей организации (кроме субъектов, которые вправе не использовать печать).",
                     "Выдаёт журнал генподрядчик (подрядчик) или застройщик лицу, ответственному за производство работ, назначенному приказом. Он же хранит журнал на объекте и отвечает за сохранность.",
                     "Ошибочные записи исправляют так, чтобы были видны дата, основание и автор исправления, а первоначальная запись оставалась читаемой.",
                     "При консервации объекта журнал передают заказчику (застройщику) или, если это предусмотрено договором, оставляют у генподрядчика.",
                     "При сдаче объекта журнал предъявляют приёмочной комиссии и после приёмки передают на постоянное хранение заказчику (застройщику), а если объект передают на баланс эксплуатирующей организации, — ей.",
                     "В записях раздела 4 описывают работы по конструктивным элементам с указанием осей, отметок, этажей и помещений."]))
    s += _sec("6", "Специальные журналы",
              _p("Новая редакция Перечня называет 13 специальных журналов. Формы шести из них приведены в СН 1.03.01-2019. Для остальных нужен ТНПА на соответствующий вид работ.")
              + _tbl(["Журнал", "Где форма"], [[a, b] for a, b in SPECIAL])
              + _p("Специальный журнал формирует и заполняет тот, кто выполняет работы (как правило, субподрядчик), а перечень специальных журналов заносят в раздел 5 общего журнала. Журнал входного контроля ведут по СН 1.03.04, п. 8.6: результаты входного контроля конструкций, изделий, материалов и оборудования фиксируют в нём. Журнал авторского надзора ведут по Инструкции, утверждённой постановлением Минстройархитектуры № 39 от 04.08.2020."))
    s += _sec("7", "Электронный вид (СП 1.03.16-2024)",
              _p("Строительные правила СП 1.03.16-2024 действуют с 20.07.2024 и определяют, как формируют и ведут исполнительную документацию в электронном виде при возведении, реконструкции, модернизации и капитальном ремонте объектов классов сложности К-1–К-4. Работа идёт в информационной системе в составе ГИС «Госстройпортал».")
              + _ul(["Инициатор — заказчик (застройщик). О ведении ИД в электронном виде органу государственного строительного надзора сообщают в уведомлении о производстве СМР. После такого уведомления вести бумажные ИД не требуется.",
                     "Участники подписывают записи и акты электронной цифровой подписью уполномоченных представителей. Электронный журнал производства работ состоит из тех же семи разделов.",
                     "Исполнитель направляет участникам уведомление о готовности проектов актов и о дате и времени освидетельствования <b>не позднее чем за 1 сутки</b> до начала.",
                     "Участники проверяют проекты актов <b>в течение 3 рабочих дней</b> без выезда на объект и могут оставить замечания; исполнитель исправляет их до освидетельствования.",
                     "Акты визируют ЭЦП все участники освидетельствования <b>в течение 3 рабочих дней</b> после фактического освидетельствования.",
                     "Фотофиксация: не менее 2592×1944 пикселей, форматы JPEG, PNG или TIFF, размер от 3 до 30 Мбайт, снимки цветные и без редактирования. Нужна ли фотофиксация и приложение снимков к актам, определяет договор подряда. Подписывать акты только по фотографиям, без фактического присутствия на объекте, нельзя.",
                     "Если выявлены несоответствия, акт не подписывают: их фиксируют в журналах, а после устранения освидетельствование повторяют. Неподписанные варианты актов остаются в системе.",
                     "После окончания строительства заказчик через систему уведомляет орган ГСН об окончании строительства и о готовности реестра ИД для приёмки объекта в эксплуатацию. Затем ЭЖПР, ЭСЖПР, акты и другую ИД передают эксплуатирующей организации (раздел 9)."]))
    s += _sec("8", "По видам деятельности", _activity_table())
    s += _sec("9", "По разделам работ", _sections_table())
    s += _sec("10", "Источники",
              _ul(["Постановление Минстройархитектуры от 29.05.2024 № 47 «Об утверждении перечня исполнительной документации» (в силу с 23.07.2024).",
                   "Постановление Минстройархитектуры от 06.10.2026 № 84 «Об изменении постановления № 47» (текст по публикации на pravo.by от 21.10.2026).",
                   "СН 1.03.04-2020 «Организация строительного производства» (с Изм. № 1): п. 4.11, 8.6–8.12, прил. А, Б, Л, М.",
                   "СП 1.03.16-2024 «Документация исполнительная. Формирование и ведение в электронном виде».",
                   "СН 1.03.01-2019 «Возведение строительных конструкций, зданий и сооружений»: прил. А, Б, В, Г, Е, Ж.",
                   "СП 4.01.08-2024, СП 4.02.08-2024, СП 4.02.07-2024 и СП 4.01.07-2024: формы актов и методики испытаний; СП 4.04.06-2024: п. 6.21 (акт скрытых работ при прокладке кабеля).",
                   "СП 1.03.01-2019 «Отделочные работы», СП 1.03.02-2020 «Монтаж внутренних инженерных систем зданий и сооружений».",
                   "Тексты открыты 06.11.2026 по подписке ООО «Тэга плюс». Перед применением сверяйте формы и даты вступления в силу с действующими изданиями."])
              + _box("Что не вошло", "Формы актов и журналов, которых не было в проверенных текстах (газоснабжение, специальные формы для электроснабжения, сигнализация и связь, тепловые сети, пусконаладка, специальные журналы по грунтам и антикоррозии, табличные формы СП 4.02.07 прил. Г, Д и СП 4.01.07 прил. Г, С), на сайте не приводятся. Мы добавим их после получения первоисточников."))
    return s


def akty_body():
    opts = ""
    for gid, gname in GROUPS:
        opts += f'<optgroup label="{gname}">'
        for f in FORMS:
            if f["group"] == gid:
                opts += f'<option value="{f["id"]}">{f["short"]}</option>'
        opts += "</optgroup>"
    return (
        '<div class="idoc" id="idoc">'
        '<div class="idoc-top"><label for="idoc-form">Выберите акт</label><select id="idoc-form">' + opts + '</select></div>'
        '<p class="idoc-info" id="idoc-info"></p>'
        '<div class="idoc-grid">'
        '<div class="idoc-left"><div class="idoc-parties" id="idoc-parties" hidden></div>'
        '<form class="idoc-fields" id="idoc-fields" aria-label="Поля акта"></form></div>'
        '<div class="idoc-view"><div class="idoc-bar">'
        '<button type="button" id="idoc-print">Печать / PDF</button><button type="button" id="idoc-copy">Копировать текст</button>'
        '<button type="button" id="idoc-txt">Скачать .txt</button><button type="button" id="idoc-clear" class="ghost">Очистить</button>'
        '<span class="idoc-prog" id="idoc-prog"></span><span class="idoc-status" id="idoc-status" role="status" aria-live="polite"></span></div>'
        '<div class="idoc-paperwrap" id="idoc-paper"></div></div></div>'
        '<noscript><p class="e-note">Для заполнения нужен включённый JavaScript.</p></noscript></div>'
        + _box("Как пользоваться", "Заполните поля слева, бланк справа обновляется сразу. «Печать / PDF» откроет печать браузера: там можно выбрать «Сохранить как PDF». "
               "Подписи ставят на бумаге или заверяют ЭЦП. Данные остаются в вашем браузере и никуда не отправляются; черновик хранится только на этом устройстве, кнопка «Очистить» его удаляет.")
        + _box("Откуда формы", "Тексты форм перенесены из СН 1.03.04-2020 (прил. А, Л, М), СП 4.01.08-2024 (прил. А, Б, В, К, Л, М), СП 4.02.08-2024 (прил. А, Б, В, Г), СП 4.02.07-2024 (прил. А, Б, В, Е, Ж, П) и СП 4.01.07-2024 (прил. А, В, М, Н, П, Р). Значения в полях пишутся шрифтом, имитирующим рукописный; на печати он синий, как чернила. "
               "Это не заменяет официальное издание: перед применением сверьте форму с действующим текстом, а объём и состав комиссии с договором подряда и проектом.")
        + '<script src="/static/idoc-data.js?v=2"></script><script src="/static/idoc-core.js?v=2"></script><script src="/static/idoc.js?v=2"></script>'
    )
